import { ChangeDetectionStrategy, Component, effect, input, output } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { TranslatePipe } from '@ngx-translate/core';
import { VENDOR_STATES, VendorDetail, VendorFields } from '@org/shared-models';
import { ButtonComponent } from '@org/ui';
import { MoneyPrefixComponent } from '../counters/money-prefix';

const FIELD = 'h-10 w-full rounded-xl border border-gray-200 bg-gray-50 px-3 text-sm focus:border-brand-400 focus:bg-white focus:outline-none focus:ring-2 focus:ring-brand-100';

/**
 * The vendor master data form (vendor spec R2-R6) shared by the add and the edit panel. There is no code field: the code is
 * generated by the server (R11) and only shown on the detail. It validates what the API validates (name length, balance not
 * negative) so the common mistakes show before the request; the five bank values are sent only when at least one is filled, and
 * the API answers a partial block or a wrong shape with a catalogue message that the caller shows (R5).
 */
@Component({
  selector: 'app-vendor-form',
  standalone: true,
  imports: [ReactiveFormsModule, TranslatePipe, ButtonComponent, MoneyPrefixComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <form [formGroup]="form" (ngSubmit)="submit()" class="space-y-5">
      @if (error()) {
        <p class="rounded-xl border border-red-200 bg-red-50 p-3 text-xs text-red-600" role="alert">{{ error() }}</p>
      }
      <div class="grid gap-4 sm:grid-cols-2">
        <div class="sm:col-span-2">
          <label for="vf-name" class="mb-1 block text-sm font-semibold">{{ 'vendor.fields.name' | translate }}<span class="text-red-500" aria-hidden="true"> *</span></label>
          <input id="vf-name" formControlName="name" class="${FIELD}" />
        </div>
        <div>
          <label for="vf-state" class="mb-1 block text-sm font-semibold">{{ 'vendor.fields.state' | translate }}</label>
          <select id="vf-state" formControlName="state" class="${FIELD}">
            <option value="">{{ 'vendor.fields.noState' | translate }}</option>
            @for (s of states; track s) { <option [value]="s">{{ s }}</option> }
          </select>
        </div>
        <div>
          <label for="vf-balance" class="mb-1 block text-sm font-semibold">{{ 'vendor.fields.openingBalance' | translate }}<span class="text-red-500" aria-hidden="true"> *</span></label>
          <app-money-prefix><input id="vf-balance" type="number" step="0.01" min="0" formControlName="openingBalanceAmount" class="${FIELD}" /></app-money-prefix>
          <p class="mt-1 text-xs text-gray-500">{{ 'vendor.fields.openingBalanceHint' | translate }}</p>
        </div>
        <div>
          <label for="vf-contact" class="mb-1 block text-sm font-semibold">{{ 'vendor.fields.contactPerson' | translate }}</label>
          <input id="vf-contact" formControlName="contactPerson" class="${FIELD}" />
        </div>
        <div>
          <label for="vf-mobile" class="mb-1 block text-sm font-semibold">{{ 'vendor.fields.mobile' | translate }}</label>
          <input id="vf-mobile" formControlName="mobile" class="${FIELD}" />
        </div>
        <div>
          <label for="vf-email" class="mb-1 block text-sm font-semibold">{{ 'vendor.fields.email' | translate }}</label>
          <input id="vf-email" type="email" formControlName="email" class="${FIELD}" />
        </div>
        <div>
          <label for="vf-gstin" class="mb-1 block text-sm font-semibold">{{ 'vendor.fields.gstin' | translate }}</label>
          <input id="vf-gstin" formControlName="gstin" class="${FIELD}" />
        </div>
        <div class="sm:col-span-2">
          <label for="vf-address" class="mb-1 block text-sm font-semibold">{{ 'vendor.fields.address' | translate }}</label>
          <input id="vf-address" formControlName="address" class="${FIELD}" />
        </div>
      </div>

      <fieldset class="rounded-xl border border-gray-200 p-4" formGroupName="bank">
        <legend class="px-2 text-sm font-semibold">{{ 'vendor.bank.title' | translate }}</legend>
        <p class="mb-3 text-xs text-gray-500">{{ 'vendor.bank.hint' | translate }}</p>
        <div class="grid gap-4 sm:grid-cols-2">
          <div>
            <label for="vf-holder" class="mb-1 block text-sm font-semibold">{{ 'vendor.bank.accountHolder' | translate }}</label>
            <input id="vf-holder" formControlName="accountHolder" class="${FIELD}" />
          </div>
          <div>
            <label for="vf-bank" class="mb-1 block text-sm font-semibold">{{ 'vendor.bank.bankName' | translate }}</label>
            <input id="vf-bank" formControlName="bankName" class="${FIELD}" />
          </div>
          <div>
            <label for="vf-branch" class="mb-1 block text-sm font-semibold">{{ 'vendor.bank.branch' | translate }}</label>
            <input id="vf-branch" formControlName="branch" class="${FIELD}" />
          </div>
          <div>
            <label for="vf-ifsc" class="mb-1 block text-sm font-semibold">{{ 'vendor.bank.ifsc' | translate }}</label>
            <input id="vf-ifsc" formControlName="ifsc" class="${FIELD} uppercase" />
          </div>
          <div class="sm:col-span-2">
            <label for="vf-account" class="mb-1 block text-sm font-semibold">{{ 'vendor.bank.accountNumber' | translate }}</label>
            <input id="vf-account" inputmode="numeric" autocomplete="off" formControlName="accountNumber" class="${FIELD}" />
          </div>
        </div>
      </fieldset>

      <div class="flex justify-end gap-2 border-t border-gray-100 pt-4">
        <app-button variant="secondary" (clicked)="cancelled.emit()">{{ 'users.cancel' | translate }}</app-button>
        <app-button type="submit" [loading]="saving()">{{ submitLabel() | translate }}</app-button>
      </div>
    </form>
  `,
})
export class VendorFormComponent {
  /** The vendor being edited, or null for a new one. */
  vendor = input<VendorDetail | null>(null);
  saving = input(false);
  error = input('');
  submitLabel = input('vendor.add.submit');

  submitted = output<VendorFields>();
  cancelled = output<void>();

  readonly states = VENDOR_STATES;

  readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true, validators: [Validators.required, Validators.minLength(2), Validators.maxLength(150)] }),
    state: new FormControl('', { nonNullable: true }),
    openingBalanceAmount: new FormControl(0, { nonNullable: true, validators: [Validators.required, Validators.min(0)] }),
    contactPerson: new FormControl('', { nonNullable: true }),
    mobile: new FormControl('', { nonNullable: true }),
    email: new FormControl('', { nonNullable: true }),
    gstin: new FormControl('', { nonNullable: true }),
    address: new FormControl('', { nonNullable: true }),
    bank: new FormGroup({
      accountHolder: new FormControl('', { nonNullable: true }),
      bankName: new FormControl('', { nonNullable: true }),
      branch: new FormControl('', { nonNullable: true }),
      accountNumber: new FormControl('', { nonNullable: true }),
      ifsc: new FormControl('', { nonNullable: true }),
    }),
  });

  constructor() {
    effect(() => {
      const v = this.vendor();
      this.form.reset(
        v
          ? {
              name: v.name,
              state: v.state ?? '',
              openingBalanceAmount: v.openingBalanceAmount,
              contactPerson: v.contactPerson ?? '',
              mobile: v.mobile ?? '',
              email: v.email ?? '',
              gstin: v.gstin ?? '',
              address: v.address ?? '',
              bank: {
                accountHolder: v.bank?.accountHolder ?? '',
                bankName: v.bank?.bankName ?? '',
                branch: v.bank?.branch ?? '',
                accountNumber: v.bank?.accountNumber ?? '',
                ifsc: v.bank?.ifsc ?? '',
              },
            }
          : { name: '', state: '', openingBalanceAmount: 0 },
      );
    });
  }

  submit(): void {
    if (this.form.invalid || this.saving()) {
      this.form.markAllAsTouched();
      return;
    }

    const v = this.form.getRawValue();
    const bank = {
      accountHolder: v.bank.accountHolder.trim(),
      bankName: v.bank.bankName.trim(),
      branch: v.bank.branch.trim(),
      accountNumber: v.bank.accountNumber.trim(),
      ifsc: v.bank.ifsc.trim().toUpperCase(),
    };
    const hasBank = Object.values(bank).some((value) => value !== '');

    this.submitted.emit({
      name: v.name.trim(),
      openingBalanceAmount: Math.round(v.openingBalanceAmount * 100) / 100,
      state: v.state,
      contactPerson: v.contactPerson.trim(),
      mobile: v.mobile.trim(),
      email: v.email.trim(),
      gstin: v.gstin.trim(),
      address: v.address.trim(),
      bank: hasBank ? bank : undefined,
    });
  }
}
